         if (version === requestVersion.current) setError(cause instanceof Error ? cause.message : 'Không thể tải danh sách hợp đồng.');
       })
       .finally(() => {
         if (version === requestVersion.current) setLoading(false);
       });
     return () => { requestVersion.current += 1; };
