       await this.audit.write(tx, {
         actor,
         action: 'loan_product.formula.version.created',
         targetType: 'loan_product',
         targetId: product.id,
         branchId: product.branchId,
         afterState: { version, variableCount: variables.length },
         requestId: requestId(request),
       });
       return formula;
     });
   }

