@'
import { unlink } from 'node:fs/promises';
import { join } from 'node:path';
import pg from 'pg';

const fileNames = ['p0-2-contract-browser-upload.pdf', 'p0-2-contract-browser-replacement.pdf'];
const storageDirectory = 'D:\\IT\\HF_CRM\\apps\\api\\src\\Assets\\contracts';
const db = new pg.Client({ connectionString: process.env.DATABASE_URL });
await db.connect();
try {
  const { rows } = await db.query('SELECT "id", "contractId", "storageKey" FROM "LoanContractDocument" WHERE "fileName" = ANY($1::text[])', [fileNames]);
  for (const row of rows) {
    try { await unlink(join(storageDirectory, row.storageKey)); }
    catch (error) { if (error?.code !== 'ENOENT') throw error; }
  }
  const contractIds = [...new Set(rows.map(({ contractId }) => contractId))];
  let historiesRemoved = 0;
  if (contractIds.length) {
    const result = await db.query(`DELETE FROM "LoanContractChangeHistory"
      WHERE "contractId" = ANY($1::uuid[])
        AND (("beforeState"->>'fileName') = ANY($2::text[]) OR ("afterState"->>'fileName') = ANY($2::text[]))`, [contractIds, fileNames]);
    historiesRemoved = result.rowCount ?? 0;
  }
  const documentsRemoved = rows.length
    ? (await db.query('DELETE FROM "LoanContractDocument" WHERE "id" = ANY($1::uuid[])', [rows.map(({ id }) => id)])).rowCount ?? 0
    : 0;
  console.log(JSON.stringify({ documentsRemoved, historiesRemoved, filesUnlinked: rows.length }));
} finally {
  await db.end();
}
