         --muted: #707070;        /* chữ phụ, label, placeholder, icon phụ. 4.95:1 */
         /* Hai token viền, chia theo vai (M14). --border: đường tóc trang trí (viền card,
            đường chia). --border-strong: viền ô nhập, nút outline, đường kẻ khung app
            (dưới header), viền card khi hover. */
         --border: #f7f7f8;
         --border-strong: #eaeaea;

         --secondary: #e7e8ec;        /* nút phụ, mục đang chọn; luôn chìm hơn --surface */
