 #!/usr/bin/env node
 // Mở trang thật ở nhiều bề rộng, đo những lỗi máy đo được, chụp ảnh để mắt soi phần còn lại.
 // Dùng ở cổng 3 của checklist (references/checklist.md). Chỉ đọc trang, không sửa gì.
 //
 //   node probe.mjs <url> [--widths 375,768,1024,1280,1440,1920] [--out <thư mục>] [--dark] [--wait 800] [--dpr 1]
 //                        [--sweep [1440,375,20]] [--wireframe <link phương án đã chọn>] [--quick]
 //                        [--dynamic-widths 1280,375|none] [--storage-state <tệp Playwright>] [--login]
 //
 // Phép đo động (Tab, rê chuột, bấm, mở lớp nổi) chiếm phần lớn thời gian mà ít đổi theo bề rộng, nên mặc định
 // chỉ chạy ở các khổ mobile, khổ gần 768 và gần 1280 nhất; khổ khác đo trang đứng yên.
 // --dynamic-widths: chọn khổ chạy phép đo động, "none" là không khổ nào. Vòng sửa thứ hai trở đi truyền đúng các
 // khổ vòng trước còn lỗi động (cuối báo cáo in sẵn lệnh).
 //
 // --quick: chỉ đo trang đứng yên (bố cục, chữ, tràn, tương phản, control gốc kể cả trong lớp đang ẩn), bỏ Tab,
 // rê chuột, bấm, mở lớp nổi. Vòng đầu cho wireframe (design-process.md, U3): ~4 lần nhanh hơn, rồi bước
 // tự rà của U3 chạy --sweep đủ phần động trước khi gửi.
 //
 // --wireframe: so bản dựng với wireframe đã chọn (design-process.md, U4) ở 1440 và 375: khoảng nào cao thấp khác,
 // chữ nào đổi hay thiếu, cỡ chữ, độ đậm nào khác; link có mau=mau thì so cả màu chữ, màu icon, nền. Ghi vào danh sách P.
 //
 // --stress: bơm dữ liệu khó vào trang trước khi đo (SKILL.md, S8): tên, tiêu đề trong ô bảng, dòng danh sách,
 // tiêu đề card dài ra ~60 ký tự; số tiền, số đếm thành số chín, mười chữ số cùng kiểu phân cách. Chỉ đo trang
 // đứng yên (như --quick), mặc định hai khổ 375 và 1280, ảnh đuôi "-stress". Lỗi báo ra là chỗ vỡ khi gặp dữ
 // liệu thật: chữ tràn, cột nở, nút xuống dòng, số bị cắt.
 //
 // --sweep: đo xong các khổ cố định thì kéo bề rộng từ 1440 xuống 375, mỗi bước 20px, chụp từng bước và
 // báo khoảng bề rộng có lỗi (cuộn ngang, khung giấu chữ, chữ trong nút xuống dòng, hàng rớt dòng, chữ cắt
 // nuốt mất số hay còn quá ngắn). Bắt
 // lỗi nằm giữa hai khổ cố định, ví dụ nav xuống dòng ở 900px. Dùng ở nhánh soi UI (references/review.md).
 //
 // Playwright tìm theo thứ tự: --pw <thư mục có node_modules/playwright>, thư mục đang đứng, thư mục script.
 // Chưa có thì cài vào một thư mục tạm, đừng cài vào dự án:
 //   npm i --prefix "$TMPDIR/evon-probe" playwright && node probe.mjs <url> --pw "$TMPDIR/evon-probe"

 import { createRequire } from "node:module";
 import { mkdirSync, writeFileSync } from "node:fs";
 import { tmpdir } from "node:os";
 import { dirname, join, resolve } from "node:path";
 import { fileURLToPath } from "node:url";

 const defaultWidths = [375, 768, 1024, 1280, 1440, 1920];
 const defaultSweep = [1440, 375, 20];
 const stressWidths = [375, 1280];
 const mobileWidthLimit = 640;
 // Sàn cỡ bấm của skill: nút h-8 trong bảng dày là nhỏ nhất được phép (list-row.md).
 const minTapSize = 32;
 // Số lần bấm Tab tối đa, và số phần tử cùng kiểu (cùng thẻ + class) được chụp so: nút thứ ba trở đi của
 // 8 card giống nhau thì Tab lướt qua, để trang nhiều card vẫn đi tới được nút nổi ở cuối trang.
 const maxTabStops = 160;
 const maxFocusChecksPerKind = 2;

 function parseArgs(argv) {
   const options = { url: "", widths: defaultWidths, out: "", isDark: false, waitMs: 800, dpr: 1, playwrightDir: "", sweep: null, wireframeUrl: "", isQuick: false, isStress: false, dynamicWidths: null, storageState: "", isAuthenticated: false };
   const rest = [...argv];

   while (rest.length > 0) {
     const arg = rest.shift();

     if (arg === "--widths") options.widths = rest.shift().split(",").map(Number);
     else if (arg === "--sweep") {
       const [from, to, step] = /^\d+,\d+(,\d+)?$/.test(rest[0] ?? "") ? rest.shift().split(",").map(Number) : defaultSweep;
       options.sweep = { from: Math.max(from, to), to: Math.min(from, to), step: step || defaultSweep[2] };
     }
     else if (arg === "--out") options.out = rest.shift();
     else if (arg === "--dark") options.isDark = true;
     else if (arg === "--wait") options.waitMs = Number(rest.shift());
     else if (arg === "--dpr") options.dpr = Number(rest.shift());
     else if (arg === "--pw") options.playwrightDir = rest.shift();
     else if (arg === "--storage-state") options.storageState = rest.shift();
     else if (arg === "--login") options.isAuthenticated = true;
     else if (arg === "--wireframe") options.wireframeUrl = rest.shift();
     else if (arg === "--quick") options.isQuick = true;
     else if (arg === "--stress") options.isStress = true;
     else if (arg === "--dynamic-widths") {
       const value = rest.shift() ?? "";
       options.dynamicWidths = new Set(value === "none" ? [] : value.split(",").map(Number));
     }
     else if (!arg.startsWith("--")) options.url = arg;
   }

   // Wireframe ở Khổ Mobile chỉ là iframe 375: probe không đo được bên trong, chỉ báo "iframe lòi ra", và
   // bản thiết kế tràn ngang trong khung lọt qua (đo 12/10/2026). Đo thẳng trang ở khổ desktop, ở 375 media
   // query chạy y như trong khung.
   if (/[?&]kho=mobile\b/.test(options.url) && !/[?&]frame=/.test(options.url)) {
     options.url = options.url.replace(/([?&]kho=)mobile\b/, "$1desktop");
     console.log(`Link wireframe Khổ Mobile là iframe, đo thẳng trang: ${options.url}`);
   }

   if (!options.out) options.out = join(tmpdir(), `evon-probe-${Date.now()}`);
   if (options.isStress && !argv.includes("--widths")) options.widths = stressWidths;
   if (options.isQuick || options.isStress) options.dynamicWidths = new Set();
   if (!options.dynamicWidths) options.dynamicWidths = pickDefaultDynamicWidths(options.widths);

   return options;
 }

 // Khổ mobile nào cũng đo động (menu, sheet chỉ mở ở màn hẹp). Trên đó hai khổ: gần 1280, và gần 768 vì bố cục
 // tablet có control riêng (đo 05/10/2026: nút "Mục lục" chỉ hiện ở 768, Tab tới không thấy gì; lớp nổi lòi khỏi
 // màn hẹp mà 1280 không lòi). 1024, 1440, 1920 đo động không ra thêm lỗi nào đáng kể.
 function pickDefaultDynamicWidths(widths) {
   const mobileWidths = widths.filter((width) => width < mobileWidthLimit);
   const desktopWidths = widths.filter((width) => width >= mobileWidthLimit);
   const closestTo = (target) => desktopWidths.reduce((best, width) => (best === null || Math.abs(width - target) < Math.abs(best - target) ? width : best), null);

   return new Set([...mobileWidths, closestTo(768), closestTo(1280)].filter((width) => width !== null));
 }

 function loadPlaywright(playwrightDir) {
   const searchDirs = [playwrightDir, process.cwd(), fileURLToPath(new URL(".", import.meta.url))].filter(Boolean);

   for (const searchDir of searchDirs) {
     try {
       return createRequire(join(resolve(searchDir), "noop.js"))("playwright");
     } catch {
       // Thử thư mục kế tiếp.
     }
   }

   return null;
 }

 async function launchBrowser(chromium) {
   try {
     return await chromium.launch();
   } catch {
     // Chưa tải Chromium của Playwright thì dùng Chrome đã cài trên máy.
     return chromium.launch({ channel: "chrome" });
   }
 }

 function createProbeContext(browser, options, contextOptions) {
   return browser.newContext({
     ...(options.storageState ? { storageState: options.storageState } : {}),
     ...contextOptions,
   });
 }

 async function authenticateProbePage(page, options, url) {
   if (!options.isAuthenticated) return;
   const target = new URL(url);
   if (target.origin !== new URL(options.url).origin) return;

   const username = process.env.PROBE_USERNAME;
   const password = process.env.PROBE_PASSWORD;
   if (!username || !password) {
     throw new Error("--login requires PROBE_USERNAME and PROBE_PASSWORD environment variables");
   }

   await page.goto(new URL("/login", target).href, { waitUntil: "load" });
   await page.locator("#username").fill(username);
   await page.locator("#password").fill(password);
   await page.getByRole("button", { name: "Đăng nhập" }).click();
   await page.waitForURL((current) => current.origin === target.origin && current.pathname !== "/login", { timeout: 15_000 });
 }

