         document.getElementById("modal-kicker").textContent = screen === "product" ? "Chi tiết sản phẩm vay" : "Chi tiết hợp đồng";
         document.getElementById("modal-title").textContent = item.title;
         modalBody.innerHTML = screen === "product" ? productBody(item) : contractBody(item);
         document.getElementById("desktop-detail").innerHTML = `<h3 class="text-xs font-medium uppercase text-crm-muted">Chi tiết</h3><h4 class="mt-2 break-words text-lg font-semibold">${item.title}</h4><p class="mt-2 text-sm text-crm-muted">${screen === "product" ? `${item.type} · ${item.branch}` : `${item.customer} · ${item.package}`}</p>`;
       }
       function setOption(value) {
         option = value;
         modalLayer.dataset.v = value;
         document.querySelectorAll("[data-option]").forEach((button) => button.setAttribute("aria-pressed", String(button.dataset.option === value)));
         const [title, summary, lines] = optionCopy[value];
         document.getElementById("reason").innerHTML = `<h3 class="text-sm font-semibold">${title}</h3><p class="mt-1 text-sm text-crm-muted">${summary}</p><p class="mt-1 text-xs text-crm-muted">${lines}</p><p class="mt-2 text-xs text-crm-muted">Tự rà: đầu, thân cuộn, nút Đóng luôn thấy; nền ngoài không đóng; mobile 375px.</p>`;
         updateUrl();
       }
       function setSize(value) {
         size = value;
         app.dataset.kho = value;
         previewDevice.dataset.kho = value;
         document.querySelectorAll("[data-size]").forEach((button) => button.setAttribute("aria-pressed", String(button.dataset.size === value)));
         updateUrl();
         renderList();
         renderDetail();
       }
       function updateUrl() {
         const query = new URLSearchParams({ v: option, man: screen === "contract" ? "hop-dong" : "san-pham", kho: size, mau: color === "gray" ? "xam" : "mau", tt: state === "data" ? "du-lieu" : state });
         if (compact) query.set("gon", "1");
         history.replaceState(null, "", `?${query.toString()}`);
       }
       document.querySelectorAll("[data-option]").forEach((button) => button.addEventListener("click", () => setOption(button.dataset.option)));
       document.querySelectorAll("[data-screen]").forEach((button) => button.addEventListener("click", () => {
         screen = button.dataset.screen;
         selectedId = currentItems()[0].id;
         document.querySelectorAll("[data-screen]").forEach((item) => item.setAttribute("aria-pressed", String(item === button)));
         renderList(); renderDetail(); updateUrl();
       }));
       document.querySelectorAll("[data-size]").forEach((button) => button.addEventListener("click", () => setSize(button.dataset.size)));
       document.getElementById("color-toggle").addEventListener("click", (event) => {
         color = color === "gray" ? "color" : "gray";
         app.dataset.color = color;
         event.currentTarget.setAttribute("aria-pressed", String(color === "color"));
         event.currentTarget.textContent = color === "color" ? "Màu" : "Xám";
         updateUrl();
       });
       document.getElementById("copy-toggle").addEventListener("click", (event) => {
         compact = !compact;
         event.currentTarget.setAttribute("aria-pressed", String(compact));
         event.currentTarget.textContent = compact ? "Gọn chữ" : "Đủ nội dung";
         document.body.classList.toggle("compact-copy", compact);
         updateUrl();
       });
       document.getElementById("state-choice").addEventListener("change", (event) => {
         state = event.currentTarget.value;
         updateUrl();
         renderList();
       });
       document.getElementById("close-modal").addEventListener("click", () => {
         modalLayer.style.display = "none";
       });
       document.getElementById("modal-layer").addEventListener("click", (event) => {
         if (event.target === modalLayer) event.preventDefault();
       });
       document.addEventListener("keydown", (event) => {
         if (event.key === "Escape" && modalLayer.style.display !== "none") event.preventDefault();
       });
       setOption(option);
       app.dataset.color = color;
       setSize(size);
       screen = params.get("man") === "hop-dong" ? "contract" : "product";
       selectedId = currentItems()[0].id;

