Set-Location apps\web; @'
const { chromium } = require(process.env.TEMP + '\\evon-probe\\node_modules\\playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  const contract = { id: 'contract-1', customerId: 'customer-1', customerName: 'Nguyen Thi Phuong Thao', branchId: 'branch-1', branchName: 'Ha Noi', canReview: true, contractNumber: 'HD-TEST-001', packageCode: 'LP-1', packageName: 'Goi vay thu nghiem', packageVersion: '1', loanType: 'Goi ho tro ngan han', termMonths: 12, loanAmount: '12000000', annualInterestRate: '8.45', monthlyPayment: '1120000', loanProduct: null, status: 'PENDING_REVIEW', approvedAt: null, completedAt: null, createdAt: '2026-01-01T00:00:00Z' };
  await page.route('**/api/v1/**', async route => {
    const path = new URL(route.request().url()).pathname;
    let body = {};
    if (path.endsWith('/auth/refresh')) body = { accessToken: 'browser-test-token', passwordChangeRequired: false };
    else if (path.endsWith('/auth/me')) body = { id: 'user-1', username: 'admin', displayName: 'Admin', status: 'ACTIVE', type: 'STAFF', mustChangePassword: false, roles: [], permissions: ['loan-products.read', 'loan-products.manage', 'loan-products.publish', 'loan-products.formula.manage', 'branches.read', 'loan-contracts.read', 'loan-contracts.review', 'loan-contracts.manage'].map(key => ({ key, scopes: ['*'] })) };
    else if (path.endsWith('/capabilities')) body = { contractCompletionOtp: { status: 'ready', ready: true, messageVi: '' } };
    else if (path.endsWith('/loan-products')) body = [{ id: 'product-1', branchId: null, branch: null, code: 'LP-1', name: 'San pham thu nghiem', loanType: 'Goi ho tro ngan han', source: 'Test', description: 'Mo ta san pham', sourceUrl: null, thumbnailUrl: null, minTermMonths: 1, maxTermMonths: 12, minAmount: null, maxAmount: null, annualInterestRate: '8.45', status: 'ACTIVE', currentFormulaVersion: 1, createdAt: '2026-01-01T00:00:00Z', updatedAt: '2026-01-01T00:00:00Z' }];
    else if (path.endsWith('/formula')) body = { version: 1, interestFormula: 'principal * annualRatePercent / 100', monthlyPaymentFormula: 'principal / termMonths', variables: [] };
    else if (path.includes('/formula-versions')) body = { items: [], nextBeforeVersion: null };
    else if (path.endsWith('/access/branches')) body = [];
    else if (path.includes('/loan-contracts') && !path.includes('/documents') && !path.includes('/history')) body = { items: [contract], pageSize: 20, nextCursor: null };
    else if (path.endsWith('/documents')) body = [];
    else if (path.endsWith('/history')) body = { items: [] };
    await route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify(body) });
  });
  const checkSheet = async (label) => {
    await page.setViewportSize({ width: 375, height: 812 });
    await page.waitForTimeout(100);
    const initialVisible = await page.getByRole('dialog').isVisible().catch(() => false);
    const trigger = label === 'product' ? page.getByRole('button', { name: /San pham thu nghiem/ }) : page.getByText('HD-TEST-001', { exact: true });
    await trigger.click();
    const dialog = page.getByRole('dialog');
    await dialog.waitFor({ state: 'visible', timeout: 5000 });
    const box = await dialog.boundingBox();
    await page.keyboard.press('Escape');
    const escapeStayedOpen = await dialog.isVisible();
    await page.mouse.click(180, 20);
    const backdropStayedOpen = await dialog.isVisible();
    await dialog.getByRole('button', { name: 'Đóng' }).click();
    await dialog.waitFor({ state: 'hidden' });
    const dimensions = await page.evaluate(() => ({ viewport: document.documentElement.clientWidth, page: document.body.scrollWidth }));
    return { label, initialVisible, box, escapeStayedOpen, backdropStayedOpen, dimensions };
  };
  await page.goto('http://localhost:3002/loan-products');
  await page.locator('main main h1').waitFor({ timeout: 10000 });
  const productResult = await checkSheet('product');
  await page.goto('http://localhost:3002/loan-contracts');
  await page.getByText('HD-TEST-001', { exact: true }).waitFor({ timeout: 10000 });
  const contractResult = await checkSheet('contract');
  await page.setViewportSize({ width: 1280, height: 900 });
  await page.waitForTimeout(150);
  const desktopRegion = await page.getByRole('region', { name: /HD-TEST-001/ }).isVisible().catch(() => false);
  console.log(JSON.stringify({ productResult, contractResult, desktopRegion }));
  await browser.close();
})().catch(error => { console.error(error); process.exitCode = 1; });
