   await db.query('INSERT INTO "UserRoleGrant" ("id","userId","roleId","branchId","scopeAnchor","createdAt") VALUES ($1,$2,$3,NULL,\'GLOBAL\',NOW())', [randomUUID(), operatorId, operatorRole.rows[0].id]);
 }

 async function cleanup() {
