@'
const fs = require('node:fs');
const path = require('node:path');
const dotenv = require('dotenv');
const { Client } = require('pg');
dotenv.config({ path: '.env.test', override: true });
const databaseName = 'finance_crm_legacy_upgrade_20261118';
const baseUrl = new URL(process.env.DATABASE_URL);
const adminUrl = new URL(baseUrl); adminUrl.pathname = '/postgres';
(async () => {
  const admin = new Client({ connectionString: adminUrl.toString() });
  await admin.connect();
  const existing = await admin.query('SELECT 1 FROM pg_database WHERE datname = $1', [databaseName]);
  if (existing.rowCount) throw new Error('Legacy test database already exists; refusing to overwrite it.');
  await admin.query(`CREATE DATABASE "${databaseName}"`);
  await admin.end();
  const targetUrl = new URL(baseUrl); targetUrl.pathname = `/${databaseName}`;
  const db = new Client({ connectionString: targetUrl.toString() });
  await db.connect();
  const initialMigrations = [
    '20261105000000_p0_1_access_control',
    '20261107000000_p0_2_customer_loan_workflow',
    '20261107010000_duplicate_candidate_current_state',
  ];
  for (const migration of initialMigrations) {
    const sql = fs.readFileSync(path.join('apps/api/prisma/migrations', migration, 'migration.sql'), 'utf8');
    await db.query(sql);
    console.log(`Applied legacy schema stage: ${migration}`);
  }
  await db.query(`INSERT INTO "Branch" ("id","code","name","status","createdAt","updatedAt") VALUES
    ('00000000-0000-4000-8000-000000000101','LEGACY-CI','Legacy migration test branch','ACTIVE',NOW(),NOW())`);
  await db.query(`INSERT INTO "Customer" ("id","fullName","normalizedName","phone","phoneNormalized","provenance","status","branchId","createdAt","updatedAt") VALUES
    ('00000000-0000-4000-8000-000000000102','Synthetic Legacy Customer','synthetic legacy customer','0911111111','0911111111','legacy migration fixture','IN_PROGRESS','00000000-0000-4000-8000-000000000101',NOW(),NOW())`);
  await db.query(`INSERT INTO "LoanContract" ("id","customerId","branchId","contractNumber","packageName","loanType","termMonths","createdAt","updatedAt") VALUES
    ('00000000-0000-4000-8000-000000000103','00000000-0000-4000-8000-000000000102','00000000-0000-4000-8000-000000000101','LEGACY-CI-0001','Legacy package','Consumer',24,NOW(),NOW())`);
  await db.end();
  console.log(`Seeded one synthetic pre-approval customer/contract in ${databaseName}.`);
})().catch((error) => { console.error(error.message); process.exitCode = 1; });
